# patch_s144_unified_text_card.py
#
# THE PROBLEM (as reported):
#   "Text on the video" was three separate cards in the الآية
#   tab: the Quran-matched "اكتب نص الآية" card, PATCH_S143's stacked
#   "طبقات نص ثابتة" card, and a third caption card further down the same
#   tab (reciter name / ayah range). Three boxes for one job, each with
#   its own explanation and its own button, and no single place that shows
#   everything actually on the video right now -- unlike every mainstream
#   video editor (InShot etc.), which shows one list of text elements with
#   one edit pencil and one delete X per row.
#
# THE FIX:
#   One card, "النص على الفيديو": a single list of every text element
#   currently on the video (ayah, then caption, then every free layer, in
#   that fixed order) with an edit pencil and a delete X per row, plus one
#   "+ إضافة نص" button that opens a single add/edit bottom sheet shared
#   by all three kinds. A fresh add starts on the free-layer kind with
#   three chips to switch kind; switching to آية/تسمية pre-fills
#   whatever is already set there instead of showing a misleadingly blank
#   field. Editing an existing row locks the kind -- you can't turn a
#   caption into a layer by fiddling with it after the fact.
#
#   Nothing about WHAT each kind does changes underneath: ayah text still
#   runs through the same Quran matcher (_applyCustomText), captions still
#   write state.captionText/captionPosition, layers still go through
#   state.addTextLayer/updateTextLayerAt/removeTextLayerAt exactly as
#   PATCH_S143 left them. This patch only changes how you reach those
#   three actions -- one door instead of three.
#
# WHAT THIS PATCH TOUCHES:
#   lib/screens/home_screen.dart only:
#     1. A new top-level `_TextKind` enum (ayah / caption / layer).
#     2. Three new State fields tracking the add/edit sheet's current
#        kind, whether it's editing (vs adding fresh), and (for layers
#        only) which index is being edited.
#     3. The old ayah-matching card + S143's layers card, previously two
#        back-to-back _sectionCard(...) blocks in the آية tab's build
#        list, replaced by a single _unifiedTextCard() call.
#     4. The standalone _captionSection() call removed from the same
#        build list (the method itself is left in place, just uncalled,
#        in case a future patch wants it back).
#     5. A new block of methods -- _unifiedTextCard, _textElementsList,
#        _textElementRow, _textKindTitle, _openTextSheet, _textSheetBody,
#        _ayahSheetFields, _captionSheetFields, _layerSheetFields --
#        inserted right after _captionSection()'s own closing brace.
#
#   Nothing in lib/models/studio_state.dart, lib/services/overlay_renderer.dart,
#   lib/services/export_service.dart or lib/widgets/stage_preview.dart is
#   touched -- this is a home_screen.dart-only UI reorganization. Preview
#   and export rendering (which all read state.ayahText/captionText/
#   textLayers directly) are unaffected.
#
# NOT covered by this patch (flagged rather than guessed at):
#   - Per-element drag-to-reposition from the list (still top/center/
#     bottom slots for layers, same as S143; the ayah text keeps whatever
#     drag behavior it already had, unchanged).
#   - Multi-language strings for this feature -- languages are a separate
#     pass, deliberately not part of this patch.
#
# Run from the project root (same convention as the other patch_sNNN
# scripts in this repo). Requires PATCH_S143_TEXT_LAYERS to already be
# applied (this patch edits code S143 introduced).

from pathlib import Path

ROOT = Path(__file__).resolve().parent
LEDGER = []


def _log(label, status):
    LEDGER.append((label, status))


def apply_literal(rel_path, old, new, label, skip_if=None):
    p = ROOT / rel_path
    if not p.exists():
        raise SystemExit(f"ERROR ({label}): {rel_path} not found under {ROOT}")
    text = p.read_text(encoding="utf-8")
    if skip_if and skip_if in text:
        _log(label, "SKIPPED-ALREADY")
        return
    n = text.count(old)
    if n != 1:
        raise SystemExit(f"ERROR ({label}): expected 1 match, found {n} in {rel_path} "
                          f"-- refusing to guess, no changes made.")
    p.write_text(text.replace(old, new, 1), encoding="utf-8")
    _log(label, "APPLIED")


HOME_SCREEN = "lib/screens/home_screen.dart"


